import { createRouter, createWebHistory } from 'vue-router'
import store from '../store'

// Composants
import Login from '../views/Login.vue'
import Register from '../views/Register.vue'
import VerifyEmail from '../views/VerifyEmail.vue'
import Dashboard from '../views/Dashboard.vue'
import CryptoDetail from '../views/CryptoDetail.vue'

const routes = [
  {
    path: '/',
    redirect: '/dashboard'
  },
  {
    path: '/login',
    name: 'Login',
    component: Login,
    meta: { requiresGuest: true }
  },
  {
    path: '/register',
    name: 'Register',
    component: Register,
    meta: { requiresGuest: true }
  },
  {
    path: '/verify-email',
    name: 'verify-email',
    component: VerifyEmail,
    meta: { requiresGuest: true }
  },
  {
    path: '/dashboard',
    name: 'Dashboard',
    component: Dashboard,
    meta: { requiresAuth: true }
  },
  {
    path: '/wallet',
    name: 'Wallet',
    component: () => import('../views/Wallet.vue'),
    meta: { requiresAuth: true }
  },
  {
    path: '/trade/:symbol',
    name: 'Trade',
    component: () => import('../views/Trade.vue'),
    meta: { requiresAuth: true }
  },
  {
    path: '/crypto/:symbol',
    name: 'CryptoDetail',
    component: CryptoDetail,
    meta: { requiresAuth: true }
  },
  {
    path: '/admin/login',
    name: 'AdminLogin',
    component: () => import('../views/AdminLogin.vue'),
    meta: { requiresGuest: true }
  },
  {
    path: '/admin/dashboard',
    name: 'AdminDashboard',
    component: () => import('../views/AdminDashboard.vue'),
    meta: { requiresAdmin: true }
  },
  {
    path: '/verify-withdrawal',
    name: 'VerifyWithdrawal',
    component: () => import('../views/VerifyWithdrawal.vue'),
    meta: { requiresAuth: true }
  }
]

const router = createRouter({
  history: createWebHistory(),
  routes
})

// Navigation Guards
router.beforeEach(async (to, from, next) => {
  const token = localStorage.getItem('token')
  const isTokenValid = token && typeof token === 'string' && token.split('.').length === 3
  const isAuthenticated = store.getters['auth/isAuthenticated']

  if (to.meta.requiresAuth) {
    if (!isTokenValid) {
      store.dispatch('auth/logout')
      next('/login')
    } else if (!isAuthenticated) {
      try {
        await store.dispatch('auth/checkAuth')
        next()
      } catch (error) {
        store.dispatch('auth/logout')
        next('/login')
      }
    } else {
      next()
    }
  } else if (to.meta.requiresAdmin) {
    const isAdmin = store.getters['admin/isAdmin']
    if (!isAdmin) {
      next('/admin/login')
    } else {
      next()
    }
  } else if (to.meta.requiresGuest && isAuthenticated) {
    next('/dashboard')
  } else {
    next()
  }
})

export default router
